import React, { useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { useApp } from "../../lib/AppContext";
import { officers, statuses, formatLabel } from "../../lib/reportData";
import SeverityBadge from "../ui/SeverityBadge";
import StatusBadge from "../ui/StatusBadge";
const ReportDetailModal = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { reports, updateReport, notify } = useApp();
  const report = reports.find((item) => item.id === id);
  const [note, setNote] = useState("");
  const [notes, setNotes] = useState([]);
  if (!report)
    return (
      <div className="rounded-xl border border-gray-100 bg-white p-10 text-center text-gray-600">
        <h2 className="font-semibold">Report not found</h2>
        <button className="mt-3 rounded-md border border-gray-200 px-3 py-2 text-xs" onClick={() => navigate("/reports")}>
          Back to reports
        </button>
      </div>
    );
  const saveNote = () => {
    if (!note.trim()) return;
    setNotes((current) => [
      {
        text: note.trim(),
        time: new Date().toLocaleString(),
      },
      ...current,
    ]);
    setNote("");
    notify("Progress note added to case timeline");
  };
  return (
    <div
      className="fixed inset-0 z-40 flex justify-end bg-[#18251e]/60"
      onMouseDown={(event) =>
        event.target === event.currentTarget && navigate("/reports")
      }
    >
      <section className="flex h-full w-full flex-col bg-white shadow-2xl sm:max-w-[490px]">
        <div className="flex items-center justify-between border-b border-gray-100 px-5 py-4">
          <div>
            <span className="text-[9px] font-bold tracking-widest text-gray-400">CASE FILE</span>
            <h2 className="mt-1 font-['Manrope',sans-serif] text-lg font-bold">{report.id}</h2>
          </div>
          <button aria-label="Close report" className="text-2xl text-gray-500" onClick={() => navigate("/reports")}>
            ×
          </button>
        </div>
        <div className="overflow-y-auto p-5">
          <div className="mb-4 flex gap-2">
            <SeverityBadge severity={report.severity} />
            <StatusBadge status={report.status} />
          </div>
          <h3 className="mb-2 font-['Manrope',sans-serif] text-base font-bold">{report.category}</h3>
          <p className="mb-4 text-[11px] leading-relaxed text-gray-500">{report.description}</p>
          {report.image && (
            <img
              className="mb-3 h-40 w-full rounded-lg object-cover"
              src={report.image}
              alt="Citizen submitted evidence"
            />
          )}
          <div className="mb-4 flex flex-wrap gap-2">
            <button className="rounded-md border border-gray-200 px-2 py-1.5 text-[9px] text-gray-600" onClick={() => notify("Image evidence opened")}>
              ▧ View image evidence
            </button>
            <button className="rounded-md border border-gray-200 px-2 py-1.5 text-[9px] text-gray-600" onClick={() => notify("No audio evidence attached")}>
              ♫ Audio
            </button>
            <button className="rounded-md border border-gray-200 px-2 py-1.5 text-[9px] text-gray-600" onClick={() => notify("No video evidence attached")}>
              ▷ Video
            </button>
          </div>
          <div className="mb-4 grid grid-cols-2 gap-3 rounded-lg border border-gray-100 bg-gray-50 p-3">
            <div>
              <small className="mb-1 block text-[8px] font-semibold tracking-wide text-gray-400">LOCATION</small>
              <b className="text-[10px] text-gray-700">⌖ {report.location}</b>
            </div>
            <div>
              <small className="mb-1 block text-[8px] font-semibold tracking-wide text-gray-400">SUBMITTED</small>
              <b className="text-[10px] text-gray-700">{report.date}</b>
            </div>
            <div>
              <small className="mb-1 block text-[8px] font-semibold tracking-wide text-gray-400">REPORTED BY</small>
              <b className="text-[10px] text-gray-700">{report.reporter}</b>
            </div>
            <div>
              <small className="mb-1 block text-[8px] font-semibold tracking-wide text-gray-400">COORDINATES</small>
              <b className="text-[10px] text-gray-700">
                {report.lat}, {report.lon}
              </b>
            </div>
          </div>
          <label className="mb-1 mt-4 block text-[10px] font-bold text-gray-600" htmlFor="case-status">
            Case status
          </label>
          <select
            className="h-9 w-full rounded-md border border-gray-200 bg-white px-2 text-[10px] outline-green-600"
            id="case-status"
            value={report.status}
            onChange={(event) => {
              updateReport(report.id, {
                status: event.target.value,
              });
              notify("Case status updated");
            }}
          >
            {statuses.map((value) => (
              <option key={value} value={value}>
                {formatLabel(value)}
              </option>
            ))}
          </select>
          <label className="mb-1 mt-4 block text-[10px] font-bold text-gray-600" htmlFor="assigned-officer">
            Assigned officer
          </label>
          <select
            className="h-9 w-full rounded-md border border-gray-200 bg-white px-2 text-[10px] outline-green-600"
            id="assigned-officer"
            value={report.officer}
            onChange={(event) => {
              updateReport(report.id, {
                officer: event.target.value,
              });
              notify("Officer assignment updated");
            }}
          >
            {officers.map((officer) => (
              <option key={officer}>{officer}</option>
            ))}
          </select>
          <div className="mb-2 mt-5 flex items-center justify-between">
            <h3 className="font-['Manrope',sans-serif] text-xs font-bold">Case timeline</h3>
            <span className="text-[9px] text-gray-400">Latest activity</span>
          </div>
          <div className="mb-4 ml-1 border-l border-[#dbe6dd] pl-4">
            {notes.map((item, index) => (
              <div className="relative pb-4" key={`${item.time}-${index}`}>
                <i className="absolute -left-[21px] top-0.5 h-2.5 w-2.5 rounded-full border-2 border-[#e8f1eb] bg-[#57906b]" />
                <b className="block text-[10px]">Progress update</b>
                <small className="mt-1 block text-[9px] text-gray-500">
                  {item.text} · {item.time}
                </small>
              </div>
            ))}
            <div className="relative pb-4">
              <i className="absolute -left-[21px] top-0.5 h-2.5 w-2.5 rounded-full border-2 border-[#e8f1eb] bg-[#57906b]" />
              <b className="block text-[10px]">Report submitted</b>
              <small className="mt-1 block text-[9px] text-gray-500">
                {report.date} · by {report.reporter}
              </small>
            </div>
            <div className="relative pb-4">
              <i className="absolute -left-[21px] top-0.5 h-2.5 w-2.5 rounded-full border-2 border-[#e8f1eb] bg-[#57906b]" />
              <b className="block text-[10px]">Case received by NEMA</b>
              <small className="mt-1 block text-[9px] text-gray-500">Automated update · today</small>
            </div>
          </div>
          <label className="mb-1 mt-4 block text-[10px] font-bold text-gray-600" htmlFor="progress-note">
            Add progress note
          </label>
          <textarea
            className="min-h-[70px] w-full resize-y rounded-md border border-gray-200 p-2 text-[10px] outline-green-600"
            id="progress-note"
            value={note}
            onChange={(event) => setNote(event.target.value)}
            placeholder="Share an update with the case record…"
          />
          <button className="mt-2 w-full rounded-lg bg-[#185835] px-4 py-2.5 text-[11px] font-semibold text-white hover:bg-[#12472a]" onClick={saveNote}>
            Post update <span>→</span>
          </button>
          <Link
            className="mt-2 block w-full rounded-lg border border-gray-200 px-3 py-2.5 text-center text-[11px] text-gray-700"
            to={`/reports/${report.id}/chat`}
          >
            ◉ Open citizen chat
          </Link>
        </div>
      </section>
    </div>
  );
};
export default ReportDetailModal;
